import 'package:flutter/material.dart';
import '../models/case_model.dart';
import '../services/database_helper.dart';

class AddCaseScreen extends StatefulWidget {
  const AddCaseScreen({super.key});

    @override
      State<AddCaseScreen> createState() => _AddCaseScreenState();
      }

      class _AddCaseScreenState extends State<AddCaseScreen> {
        final _formKey = GlobalKey<FormState>();
          final _caseNumberController = TextEditingController();
            final _courtNameController = TextEditingController();
              final _clientNameController = TextEditingController();
                final _notesController = TextEditingController();
                  DateTime _selectedDate = DateTime.now();

                    // اختيار تاريخ الجلسة
                      Future<void> _pickHearingDate(BuildContext context) async {
                          final DateTime? picked = await showDatePicker(
                                context: context,
                                      initialDate: _selectedDate,
                                            firstDate: DateTime(2020),
                                                  lastDate: DateTime(2030),
                                                      );
                                                          if (picked != null && picked != _selectedDate) {
                                                                setState(() {
                                                                        _selectedDate = picked;
                                                                              });
                                                                                  }
                                                                                    }

                                                                                      // حفظ القضية في قاعدة البيانات
                                                                                        void _saveCase() async {
                                                                                            if (_formKey.currentState!.validate()) {
                                                                                                  final newCase = LegalCase(
                                                                                                          caseNumber: _caseNumberController.text,
                                                                                                                  courtName: _courtNameController.text,
                                                                                                                          clientName: _clientNameController.text,
                                                                                                                                  hearingDate: _selectedDate,
                                                                                                                                          notes: _notesController.text,
                                                                                                                                                );

                                                                                                                                                      await DatabaseHelper.instance.insertCase(newCase);

                                                                                                                                                            if (mounted) {
                                                                                                                                                                    Navigator.pop(context, true); // العودة للشاشة الرئيسية وتحديث القائمة
                                                                                                                                                                          }
                                                                                                                                                                              }
                                                                                                                                                                                }

                                                                                                                                                                                  @override
                                                                                                                                                                                    Widget build(BuildContext context) {
                                                                                                                                                                                        return Scaffold(
                                                                                                                                                                                              appBar: AppBar(
                                                                                                                                                                                                      title: const Text('إضافة جلسة أو قضية جديدة'),
                                                                                                                                                                                                              backgroundColor: const Color(0xFF1A237E),
                                                                                                                                                                                                                      centerTitle: true,
                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                  body: Padding(
                                                                                                                                                                                                                                          padding: const EdgeInsets.all(16.0),
                                                                                                                                                                                                                                                  child: Form(
                                                                                                                                                                                                                                                            key: _formKey,
                                                                                                                                                                                                                                                                      child: ListView(
                                                                                                                                                                                                                                                                                  children: [
                                                                                                                                                                                                                                                                                                TextFormField(
                                                                                                                                                                                                                                                                                                                controller: _caseNumberController,
                                                                                                                                                                                                                                                                                                                                decoration: const InputDecoration(labelText: 'رقم القضية / الدعوى'),
                                                                                                                                                                                                                                                                                                                                                validator: (value) => value!.isEmpty ? 'يرجى إدخال رقم القضية' : null,
                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                            const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                                                          TextFormField(
                                                                                                                                                                                                                                                                                                                                                                                                          controller: _courtNameController,
                                                                                                                                                                                                                                                                                                                                                                                                                          decoration: const InputDecoration(labelText: 'اسم المحكمة (مثال: محكمة صلح حقوق عمان)'),
                                                                                                                                                                                                                                                                                                                                                                                                                                          validator: (value) => value!.isEmpty ? 'يرجى إدخال اسم المحكمة' : null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    TextFormField(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    controller: _clientNameController,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    decoration: const InputDecoration(labelText: 'اسم الموكل'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    validator: (value) => value!.isEmpty ? 'يرجى إدخال اسم الموكل' : null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const SizedBox(height: 20),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Row(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              mainAxisAlignment: MainAxisAlignment.spaceBetween,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'تاريخ الجلسة: ${_selectedDate.toString().split(' ')[0]}',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ElevatedButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onPressed: () => _pickHearingDate(context),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    child: const Text('اختر التاريخ'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const SizedBox(height: 20),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                TextFormField(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                controller: _notesController,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                decoration: const InputDecoration(labelText: 'ملاحظات إضافية (اختياري)'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                maxLines: 3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const SizedBox(height: 30),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ElevatedButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          style: ElevatedButton.styleFrom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            backgroundColor: const Color(0xFF1A237E),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              padding: const EdgeInsets.symmetric(vertical: 14),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onPressed: _saveCase,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              child: const Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'حفظ الجلسة',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  style: TextStyle(fontSize: 18, color: Colors.white),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          